Let $\mathcal U$ be an upper cluster algebra with coefficient semifield $\mathbb P$  and  initial seed $t_0$.  Then the following statements hold.

\begin{itemize}

\item[(i)]  If $L$ is a cluster monomial of $\mathcal U$ which does not contain the initial cluster variable $A_{k;t_0}$ for some $k$, then $L/A_{k;t_0}\notin\mathcal U$, that is, $(A_{k;t_0}\mid\mid L)_v=0$.

\item[(ii)] If $L$ is a cluster monomial in non-initial cluster variables, then  $L/A_{k;t_0}\notin\mathcal U$, that is, $(A_{k;t_0}\mid\mid L)_v=0$ for $k=1,\ldots,n$.
    \item[(iii)] Let $M=\prod\limits_{i=1}^nA_{i;t}^{b_i}$ be a cluster monomial in a seed $t$ of $\mathcal U$ and $I=\{i\mid A_{i;t}\in A_{t_0}\}$, then $M=\prod\limits_{i\in I}A_{i;t}^{b_i}\cdot\prod\limits_{j\notin I}A_{j;t}^{b_j}$ is a local factorization of $M$ with respect to $t_0$.
\end{itemize}

Let $\mathcal X$ be a cluster Poisson algebra and $\mathcal U$ an upper cluster algebra of the same type as $\mathcal X$. Denote $\overline X_t$  the Poisson cluster of $\mathcal X$ at $t$ to distinguish the $\mathscr X$-cluster $X_t$ of $\mathcal U$ at $t$. Each mutation $t_k=\mu_k(t)$ gives an $\mathscr X$-exchange pair $(\overline X_{k;t},\overline X_{k;t_k})$ of $\mathcal X$ and an $\mathscr A$-exchange pair $(A_{k;t},A_{k;t_k})$ of $\mathcal U$. Then

\begin{itemize}
\item[(i)] The map $\psi:\overline X_{k;t}\mapsto (A_{k;t},A_{k;t_k})$ gives a bijection from the set of cluster Poisson variables of $\mathcal X$ to the set of  $\mathscr A$-exchange pairs of $\mathcal U$;


\item[(ii)] The map $\psi_1:(\overline X_{k;t}, \overline X_{k;t_k})\mapsto (A_{k;t},A_{k;t_k})$ gives a bijection from the set of $\mathscr X$-exchange pairs of $\mathcal X$ to  the set of $\mathscr A$-exchange pairs of $\mathcal U$.
\end{itemize}

Let $\mathcal U_{\rm uc}$ be an upper cluster algebra with universal coefficient semifield and $t, t_0$  two seeds of $\mathcal U_{\rm uc}$.
Let $\frac{X_{k;t}}{1+X_{k;t}}M_1+\frac{1}{1+X_{k;t}}M_2$ be the $k$-th exchange binomial of $t$ and $\frac{X_{j;t_0}}{1+X_{j;t_0}}N_1+\frac{1}{1+X_{j;t_0}}N_2$  the $j$-th exchange binomial of $t_0$. Then the following conditions are equivalent.

\begin{itemize}
\item[(i)] $X_{k;t}=X_{j;t_0}$;

\item[(ii)] $(A_{k;t}, M_1, M_2)=(A_{j;t_0}, N_1, N_2)$;



\item[(iii)] $(A_{k;t},\{A_{i;t}\mid b_{ik}^t\neq 0\})=(A_{j;t_0},\{A_{i;t_0}\mid b_{ij}^{t_0}\neq 0\})$;

\item[(iv)] $A_{k;t}=A_{j;t_0}$ and $\{A_{i;t}\mid b_{ik}^t\neq 0\}\subseteq A_{t_0}$;

\item[(v)] $(A_{k;t},A_{k;t^\prime})=(A_{j;t_0},A_{j;t_1})$, where $t^\prime=\mu_k(t)$ and $t_1=\mu_j(t_0)$;

\item[(vi)] $A_{k;t}=A_{j;t_0}$ and $\frac{X_{k;t}}{1+X_{k;t}}M_1+\frac{1}{1+X_{k;t}}M_2=\frac{X_{j;t_0}}{1+X_{j;t_0}}N_1+\frac{1}{1+X_{j;t_0}}N_2$.
\end{itemize}
